以下是一个简化的示例，展示如何在 `Node.js` 应用中检测和利用 Prototype Pollution 漏洞：

**检测**

```javascript
function detectPrototypePollution(obj) {
  const prototypeChain = [];
  let currentObj = obj;

  while (currentObj !== null && currentObj !== undefined) {
    prototypeChain.push(currentObj);
    currentObj = Object.getPrototypeOf(currentObj);
  }

  for (const obj of prototypeChain) {
    if (typeof obj === 'object' && !Array.isArray(obj)) {
      for (const key in obj) {
        if (!Object.prototype.hasOwnProperty.call(obj, key)) {
          console.log(`Potential Prototype Pollution detected: ${key} on object ${obj}`);
        }
      }
    }
  }
}

// Example usage
detectPrototypePollution({});
```

**利用**

```javascript
function exploitPrototypePollution(obj, key, value) {
  Object.defineProperty(obj, key, { value, writable: true });
}

const vulnerableObj = {};
exploitPrototypePollution(vulnerableObj, 'toString', () => 'attack');
console.log(vulnerableObj.toString()); // Outputs: attack
```

