DPAPI（Data Protection API）是一种数据保护应用程序接口，它允许开发人员使用加密服务对数据进行加密和解密。在Windows操作系统中，用户可以使用DPAPI保存各类密码。

DPAPI解密工具的功能是从Windows系统中提取并解密这些被保护的密码。下面提供一个C++示例代码，演示如何使用DPAPI进行加密和解密：
```cpp
#include <windows.h>
#include <stdio.h>

void EncryptData(BYTE* data, DWORD size, BYTE** encryptedData, DWORD* encryptedSize)
{
    DATA_BLOB plainText = {size, data};
    DATA_BLOB cipherText;

    if (!CryptProtectData(&plainText, NULL, NULL, NULL, NULL, 0, &cipherText))
    {
        printf("EncryptData failed with error: %d\n", GetLastError());
        return;
    }

    *encryptedData = new BYTE[cipherText.cbData];
    memcpy(*encryptedData, cipherText.pbData, cipherText.cbData);
    *encryptedSize = cipherText.cbData;

    LocalFree(cipherText.pbData);
}

void DecryptData(BYTE* encryptedData, DWORD encryptedSize, BYTE** decryptedData, DWORD* decryptedSize)
{
    DATA_BLOB cipherText = {encryptedSize, encryptedData};
    DATA_BLOB plainText;

    if (!CryptUnprotectData(&cipherText, NULL, NULL, NULL, NULL, 0, &plainText))
    {
        printf("DecryptData failed with error: %d\n", GetLastError());
        return;
    }

    *decryptedData = new BYTE[plainText.cbData];
    memcpy(*decryptedData, plainText.pbData, plainText.cbData);
    *decryptedSize = plainText.cbData;

    LocalFree(plainText.pbData);
}

int main()
{
    char data[] = "Hello, World!";

    printf("Original Data: %s\n", data);

    BYTE* encryptedData;
    DWORD encryptedSize;
    EncryptData((BYTE*)data, sizeof(data), &encryptedData, &encryptedSize);

    printf("Encrypted Data:\n");
    for (DWORD i = 0; i < encryptedSize; i++)
    {
        printf("%02X ", encryptedData[i]);
    }
    printf("\n");

    BYTE* decryptedData;
    DWORD decryptedSize;
    DecryptData(encryptedData, encryptedSize, &decryptedData, &decryptedSize);

    printf("Decrypted Data: %s\n", (char*)decryptedData);

    delete[] encryptedData;
    delete[] decryptedData;

    return 0;
}
```
这个示例代码使用CryptProtectData和CryptUnprotectData函数来执行加密和解密操作。请注意，实际的DPAPI解密工具需要在Windows系统中查询并提取用户保存的各类密码，而不是像示例代码那样手动输入明文数据。

