```csharp
[DllImport("oleaut32.dll", CharSet = CharSet.Auto)]
public static extern int CoCreateInstance(
    [MarshalAs(UnmanagedType.LPStruct)] Guid rclsid,
    IntPtr pUnkOuter,
    CLSCTX dwClsCtx,
    ref Guid riid,
    out IntPtr ppv
);

private void InitializeComObject()
{
    Guid clsid = new Guid("YOUR-GUID");
    Guid iid = typeof(IComObject).GUID;
    IntPtr punk = IntPtr.Zero;

    int hr = CoCreateInstance(clsid, IntPtr.Zero, CLSCTX.CLSCTX_REMOTE_SERVER, ref iid, out punk);

