BOOL InitEtwSession()
{
    HANDLE hSession = NULL;
    BOOL bSuccess = FALSE;

    if (FALSE == EnableEtw(ETW_LOG_SECURITY_AUDIT, EVENT_RECORD_DO_NOT_SELF_REGISTER))
    {
        goto cleanup;
    }

    if (NULL == (hSession = RegisterEventSource(NULL, TEXT("Security")))
        || NULL == hSession)
    {
        goto cleanup;
    }

    if (FALSE == AddEventSourceToEtwSession(hSession, ETW_LOG_SECURITY_AUDIT))
    {
        goto cleanup;
    }

    bSuccess = TRUE;

cleanup:
    if (hSession != NULL)
    {
        DeregisterEventSource(hSession);
    }
    return bSuccess;
}
```

Finally, create a main function to initialize the ETW session and wait for events:

```cpp
int __stdcall wmain(int argc, wchar_t* argv[])
{
