    if (NULL == hEvent)
    {
        return -1;
    }

    if (FALSE == InitEtwSession())
    {
        goto cleanup;
    }

    if (FALSE == EventRegister(EventCallback, 0, &WINEVT_LOGSECURITYGuid))
    {
