    DWORD functionAddress = (DWORD)GetProcAddress(hModule, functionName);
    if (!functionAddress)
        return 0;

    return functionAddress;
}

void UnhookSystemCall(DWORD syscallNumber) {
    PIMAGE_NT_HEADERS headers = (PIMAGE_NT_HEADERS)((ULONG_PTR)ntdll + sizeof(IMAGE_DOS_HEADER));
    PIMAGE_EXPORT_DIRECTORY exportDir = (PIMAGE_EXPORT_DIRECTORY)(headers->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress + (ULONG_PTR)ntdll);

    DWORD* functionAddresses = (DWORD*)(exportDir->AddressOfFunctions + (ULONG_PTR)ntdll);
    WORD* nameOrdinals = (WORD*)(exportDir->AddressOfNameOrdinals + (ULONG_PTR)ntdll);

    DWORD originalFunctionAddress = GetOriginalFunctionAddress("ntdll.dll", functionAddresses[nameOrdinals[syscallNumber]]);
    if (!originalFunctionAddress)
        return;

    // 这里需要注意，你必须有一个合法的指针来修改被Hook的函数指针
    // 这将恢复原始函数地址到被Hook的系统调用中
    DWORD* hookedFunctionPointer = /* 获取被Hook的函数指针 */;
    *hookedFunctionPointer = originalFunctionAddress;
}

int main() {
    HMODULE ntdll = GetModuleHandleA("ntdll.dll");
    if (!ntdll)
        return 1;

    // 循环遍历所有系统调用，并恢复被Hook的函数指针
    for (DWORD syscallNumber = 0; syscallNumber < /* 总共的系统调用数 */; ++syscallNumber) {
        UnhookSystemCall(syscallNumber);
    }

    return 0;
}
```

