#include <windows.h>
#include <iostream>

void inject_code(DWORD process_id, LPVOID code) {
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, process_id);
    if (!hProcess) {
        std::cerr << "Failed to open process\n";
        return;
    }

    LPVOID remote_code = VirtualAllocEx(hProcess, NULL, strlen((char*)code), MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!remote_code) {
        std::cerr << "Failed to allocate memory in target process\n";
        CloseHandle(hProcess);
        return;
    }

    SIZE_T written_bytes;
    if (!WriteProcessMemory(hProcess, remote_code, code, strlen((char*)code), &written_bytes)) {
        std::cerr << "Failed to write code into target process\n";
        VirtualFreeEx(hProcess, remote_code, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return;
    }

    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)remote_code, NULL, 0, NULL);
    if (!hThread) {
        std::cerr << "Failed to create remote thread\n";
        VirtualFreeEx(hProcess, remote_code, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return;
    }

    CloseHandle(hThread);
    CloseHandle(hProcess);
}

int main() {
