```solidity
pragma solidity ^0.8.0;

import "./C2Command.sol";

contract C2Commands {
    using SafeMath for uint256;

    struct CommandData {
        address sender;
        address receiver;
        bytes32 data;
        uint256 timestamp;
    }

    mapping(uint256 => CommandData) public commands;
    uint256 public commandCount;

    event NewCommand(uint256 indexed commandId);

    constructor() {}

    function storeNewCommand(address _sender, address _receiver, bytes32 _data) public {
        commandId = commandCount.add(1);
        commands[commandId] = CommandData(_sender, _receiver, _data, block.timestamp);
        emit NewCommand(commandId);
    }

    function getCommandDetails(uint256 _commandId) public view returns (address memory, address memory, bytes32 memory, uint256) {
        return commands[_commandId];
    }

    function getCommandsByAddress(address _addr) public view returns (uint256[] memory) {
        uint256[] memory commandsIds;
        for (uint256 i = 1; i <= commandCount; i++) {
            CommandData storage command = commands[i];
            if (command.sender == _addr || command.receiver == _addr) {
                commandsIds.push(i);
            }
        }
        return commandsIds;
    }
}
