#include <stdlib.h>

#define SECTOR_SIZE 512

unsigned char mbr_code[SECTOR_SIZE] = {
    // ... paste your MBR code here ...
};

int main(int argc, char *argv[]) {
    FILE *fd;
    unsigned char buf[SECTOR_SIZE];

    if (argc != 2) {
        printf("Usage: %s <device>\n", argv[0]);
        return 1;
    }

    fd = fopen(argv[1], "rb+");
    if (!fd) {
        perror("fopen");
        return 1;
    }

    fseek(fd, 0, SEEK_SET);
    fread(buf, SECTOR_SIZE, 1, fd);

    // Write your MBR code here
    fseek(fd, 0, SEEK_SET);
    fwrite(mbr_code, SECTOR_SIZE, 1, fd);

    fclose(fd);
    printf("MBR overwritten successfully.\n");
    return 0;
}
```

3. 编译并运行程序

编译 C 语言示例，并用根目录的 MBR 作为参数运行：

```sh
